package com.affinity.api;
public final class AffinityException extends RuntimeException {private final int status;private final String code,requestId;private final Double retryAfter;public AffinityException(int status,String code,String requestId,Double retryAfter){super("Affinity API request failed ("+status+")");this.status=status;this.code=code;this.requestId=requestId;this.retryAfter=retryAfter;}public int status(){return status;}public String code(){return code;}public String requestId(){return requestId;}public Double retryAfter(){return retryAfter;}public boolean retryable(){return java.util.Set.of(408,429,500,502,503,504).contains(status);}}